namespace GuiEventsLab;

// LabCheck: runs all four parts of the lab and prints what each part
// produces. Do not edit this file. Your output must match the expected
// output in the lab handout, character for character.
public static class LabCheck
{
    // The check runs when you ask for it, and always on GitHub,
    // because the GitHub machine has no screen to open a window on.
    public static bool ShouldRun(string[] args)
    {
        bool asked = args.Length > 0 && args[0] == "check";
        bool onGitHub = Environment.GetEnvironmentVariable("GITHUB_ACTIONS") == "true";
        return asked || onGitHub;
    }

    public static void Run()
    {
        Console.WriteLine("=== CSCI 1260 GUIS AND EVENTS LAB ===");
        Console.WriteLine();
        RunPart("Part A: the coffee bar announces", PartA);
        Console.WriteLine();
        RunPart("Part B: listeners", PartB);
        Console.WriteLine();
        WindowDriver.StartHeadless();
        RunPart("Part C: the window", PartC);
        Console.WriteLine();
        RunPart("Part D: buttons that know when they can work", PartD);
    }

    // A part you have not finished prints one line instead of stopping
    // the whole program, so the other parts still run.
    private static void RunPart(string title, Action part)
    {
        Console.WriteLine(title);
        try
        {
            part();
        }
        catch (NotImplementedException)
        {
            Console.WriteLine("  Not finished yet.");
        }
    }

    // ---------- Session 1: events with no window ----------

    private static void PartA()
    {
        CoffeeBar bar = new CoffeeBar();
        List<string> placed = new List<string>();
        List<string> ready = new List<string>();
        int caughtUp = 0;

        // The check is a subscriber too. It writes down what it hears,
        // and how long the line was at the moment it heard it.
        bar.OrderPlaced += (sender, e) => placed.Add($"#{e.Order.Number} (waiting {bar.WaitingCount})");
        bar.OrderReady += (sender, e) => ready.Add($"#{e.Order.Number} (waiting {bar.WaitingCount})");
        bar.AllCaughtUp += (sender, e) => caughtUp++;

        Line("Place Ada, latte:", bar.Place("Ada", "latte"));
        Line("Place Ben, mocha:", bar.Place("Ben", "mocha"));
        Line("Place a blank name:", Refused(() => bar.Place("  ", "chai")));
        Line("OrderPlaced heard:", string.Join(", ", placed));
        Line("FinishNext:", bar.FinishNext());
        Line("AllCaughtUp heard:", Times(caughtUp));
        Line("FinishNext:", bar.FinishNext());
        Line("AllCaughtUp heard:", Times(caughtUp));
        Line("OrderReady heard:", string.Join(", ", ready));
        Line("FinishNext when empty:", Refused(() => bar.FinishNext()));
    }

    private static void PartB()
    {
        CoffeeBar bar = new CoffeeBar();
        PickupScreen screen = new PickupScreen();
        Buzzer buzzer = new Buzzer();
        screen.Connect(bar);
        buzzer.Connect(bar);

        bar.Place("Ada", "latte");
        bar.Place("Ben", "mocha");
        bar.Place("Cy", "chai");
        bar.FinishNext();
        buzzer.Disconnect(bar);
        bar.FinishNext();
        bar.FinishNext();

        Console.WriteLine("  Pickup screen:");
        foreach (string line in screen.Lines())
        {
            Console.WriteLine("    " + line);
        }
        Console.WriteLine("  Buzzer, disconnected after #1:");
        foreach (string message in buzzer.Messages())
        {
            Console.WriteLine("    " + message);
        }

        Console.WriteLine("  Rewards, Cy orders three times:");
        CoffeeBar shop = new CoffeeBar();
        Rewards rewards = new Rewards();
        List<string> earned = new List<string>();
        rewards.Connect(shop);
        rewards.FreeDrinkEarned += (sender, e) => earned.Add($"{e.Order.Customer} on #{e.Order.Number}");

        shop.Place("Cy", "latte");
        shop.Place("Ada", "mocha");
        shop.Place("Cy", "chai");
        shop.Place("Cy", "latte");
        while (shop.WaitingCount > 0)
        {
            shop.FinishNext();
        }
        InnerLine("Drinks for Ada, Cy:", $"{rewards.DrinksFor("Ada")} {rewards.DrinksFor("Cy")}");
        InnerLine("FreeDrinkEarned heard:", earned.Count == 0 ? "nothing" : string.Join(", ", earned));
    }

    // ---------- Session 2: the window, driven with no screen ----------

    private static void PartC()
    {
        WindowDriver window = new WindowDriver(new MainWindow());

        window.Type("CustomerBox", "Ada");
        window.Type("DrinkBox", "latte");
        window.Click("PlaceButton");
        Line("Place Ada, latte:", window.Items("WaitingList"));
        Line("Boxes after Place:", window.Text("CustomerBox") + " " + window.Text("DrinkBox"));

        window.Type("CustomerBox", "Ben");
        window.Type("DrinkBox", "mocha");
        window.Click("PlaceButton");
        Line("Place Ben, mocha:", window.Items("WaitingList"));

        window.Click("ReadyButton");
        Line("Click Ready:", window.Items("PickupList"));
        window.Click("ReadyButton");
        Line("Click Ready again:", window.Items("PickupList"));
        Line("Waiting list:", window.Items("WaitingList"));
        Line("Status:", window.Text("StatusText"));
    }

    private static void PartD()
    {
        WindowDriver window = new WindowDriver(new MainWindow());

        Line("Place enabled, boxes empty:", window.IsEnabled("PlaceButton"));
        window.Type("CustomerBox", "Cy");
        Line("Place enabled, name only:", window.IsEnabled("PlaceButton"));
        window.Type("DrinkBox", "latte");
        Line("Place enabled, name and drink:", window.IsEnabled("PlaceButton"));
        Line("Ready enabled, none waiting:", window.IsEnabled("ReadyButton"));
        window.Click("PlaceButton");
        Line("Ready enabled, one waiting:", window.IsEnabled("ReadyButton"));

        window.Type("CustomerBox", "Cy");
        window.Type("DrinkBox", "chai");
        window.Click("PlaceButton");
        window.Type("CustomerBox", "Cy");
        window.Type("DrinkBox", "mocha");
        window.Click("PlaceButton");
        window.Click("ReadyButton");
        window.Click("ReadyButton");
        window.Click("ReadyButton");
        Line("Ready enabled, all finished:", window.IsEnabled("ReadyButton"));
        Line("Reward text:", window.Text("RewardText"));
    }

    // ---------- helpers ----------

    private static void Line(string label, object? value)
    {
        Console.WriteLine("  {0,-32}{1}", label, value);
    }

    private static void InnerLine(string label, object? value)
    {
        Console.WriteLine("    {0,-30}{1}", label, value);
    }

    private static string Times(int count)
    {
        return count == 1 ? "1 time" : $"{count} times";
    }

    // Runs one request and reports whether the class refused it.
    private static string Refused(Func<object> request)
    {
        try
        {
            request();
            return "accepted";
        }
        catch (ArgumentException ex)
        {
            return "refused: " + ex.Message;
        }
        catch (InvalidOperationException ex)
        {
            return "refused: " + ex.Message;
        }
    }
}
